window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[72]={"7201":{"example:7201:exzh":"These pants are loose.","example:7201:exzh2":"I like light exercise.","example:7201:exzh3":"He lives a relaxed life.","example:7201:exzh4":"A light headwind is blowing.","example:7201:exzh5":"This tie is a little loose."},"7202":{"example:7202:exzh":"He is skiing.","example:7202:exzh2":"The car coasted.","example:7202:exzh3":"The plane is taxiing on the runway.","example:7202:exzh4":"She is enjoying the glide.","example:7202:exzh5":"Are you good at gliding?"},"7203":{"example:7203:exzh":"I'm transporting the luggage.","example:7203:exzh2":"Transporting cargo is important.","example:7203:exzh3":"The moving work finished quickly.","example:7203:exzh4":"Carrying it all alone is tough.","example:7203:exzh5":"I made a transport plan."},"7206":{"example:7206:exzh":"Put the toys in the wooden box.","example:7206:exzh2":"This wooden box is heavy.","example:7206:exzh3":"How are wooden boxes made?","example:7206:exzh4":"What's inside the wooden box?","example:7206:exzh5":"The wooden box is very sturdy."},"7207":{"example:7207:exzh":"The child needs to be punished.","example:7207:exzh2":"He did something bad and was punished.","example:7207:exzh3":"That kind of behavior has to be punished.","example:7207:exzh4":"Punishment is part of education.","example:7207:exzh5":"It's better if the punishment isn't too harsh."},"7208":{"example:7208:exzh":"This sentence needs emphasis.","example:7208:exzh2":"The emphasized points are important.","example:7208:exzh3":"The materials include points that should be emphasized.","example:7208:exzh4":"Emphasis helps communication.","example:7208:exzh5":"He spoke without forgetting to add emphasis."},"7209":{"example:7209:exzh":"This cake has a fruit mix in it.","example:7209:exzh2":"He is an athlete in mixed sports.","example:7209:exzh3":"This album is mixed music.","example:7209:exzh4":"I'll add mixed nuts to the salad.","example:7209:exzh5":"She is wearing clothes in a mixed style."},"7210":{"example:7210:exzh":"That city has many slums.","example:7210:exzh2":"The people in the slums have a hard life.","example:7210:exzh3":"Getting out of the slums is not easy.","example:7210:exzh4":"He grew up in the slums.","example:7210:exzh5":"The slum problem is a serious social issue."},"7211":{"example:7211:exzh":"The cat scratched my hand.","example:7211:exzh2":"He got scratched by a tree.","example:7211:exzh3":"It hurts when you scratch it.","example:7211:exzh4":"The dog is scratching the ground.","example:7211:exzh5":"The child scratched up the wall."},"7212":{"example:7212:exzh":"She hopes to go on to higher education.","example:7212:exzh2":"I'm studying so I can go on to higher education.","example:7212:exzh3":"I'm looking for a school to go on to.","example:7212:exzh4":"The rate of students going on to higher education is rising.","example:7212:exzh5":"Going on to higher education is important."},"7213":{"example:7213:exzh":"He is a professional athlete who is still active.","example:7213:exzh2":"I value the time I have while still active.","example:7213:exzh3":"She is still working.","example:7213:exzh4":"Being an active player is really tough.","example:7213:exzh5":"Life as an active player is a lot of fun."},"7214":{"example:7214:exzh":"Area is measured in square meters.","example:7214:exzh2":"This plot of land is expressed in square units.","example:7214:exzh3":"You need to calculate the square root.","example:7214:exzh4":"Do you understand the concept of square numbers?","example:7214:exzh5":"Let's use the square formula."},"7216":{"example:7216:exzh":"I like country music.","example:7216:exzh2":"That countryside is beautiful.","example:7216:exzh3":"I long for country life.","example:7216:exzh4":"The countryside scenery spreads out far and wide.","example:7216:exzh5":"I'm looking forward to country cooking."},"7219":{"example:7219:exzh":"That building was occupied without permission.","example:7219:exzh2":"The reason for the occupation is rising living costs.","example:7219:exzh3":"They occupied the park.","example:7219:exzh4":"I don't have the right to occupy it.","example:7219:exzh5":"You should know the laws about occupation."},"7220":{"example:7220:exzh":"The court held a hearing.","example:7220:exzh2":"The hearing for this case starts next month.","example:7220:exzh3":"The hearing will proceed toward a verdict.","example:7220:exzh4":"The lawyer will handle the hearing.","example:7220:exzh5":"I'm waiting for the result of the hearing."},"7221":{"example:7221:exzh":"She stars in the movie.","example:7221:exzh2":"The lead actor gave a wonderful performance.","example:7221:exzh3":"The films they starred in won many awards.","example:7221:exzh4":"He often plays the lead in dramas.","example:7221:exzh5":"I've seen all the movies they starred in."},"7222":{"example:7222:exzh":"Preparation is needed to capture it alive.","example:7222:exzh2":"This animal can be captured alive.","example:7222:exzh3":"Please tell me how to capture it alive.","example:7222:exzh4":"You should think about the difference between capturing alive and killing.","example:7222:exzh5":"Capturing alive should be done carefully."},"7223":{"example:7223:exzh":"Let's go eat ramen.","example:7223:exzh2":"This is my favorite ramen shop.","example:7223:exzh3":"This ramen is delicious.","example:7223:exzh4":"There are many kinds of ramen.","example:7223:exzh5":"You can eat ramen until late at night.","grammar:7223:ex:trans":"Let's go eat ramen.","grammar:7223:ex:structure":"ラーメンを食べに＋行きましょう","grammar:7223:ex:explain":"「Verb stem (masu-form minus ます)＋に行く」 means going in order to do something, so 「食べに行く」 is going to eat. This 「に」 marks the purpose of movement, and only a verb's continuative form or an action noun can come before it, as in 「買い物に行く」. The final 「行きましょう」 is the polite form of the volitional, used to invite someone to do something together; it sounds softer than 「行きます」 and works like the English invitation let's go…","grammar:7223:ex:words:0:zh":"ramen","grammar:7223:ex:words:0:pos":"noun","grammar:7223:ex:words:1:zh":"(object marker)","grammar:7223:ex:words:1:pos":"particle","grammar:7223:ex:words:2:zh":"eat (continuative, nominalized)","grammar:7223:ex:words:2:note":"たべ","grammar:7223:ex:words:2:pos":"verb","grammar:7223:ex:words:3:zh":"(purpose)","grammar:7223:ex:words:3:pos":"particle","grammar:7223:ex:words:4:zh":"let's go (volitional)","grammar:7223:ex:words:4:note":"いきましょう","grammar:7223:ex:words:4:pos":"verb","grammar:7223:ex:points:0":"Verb continuative form＋に行く: go in order to〜 (食べに行く = go eat)","grammar:7223:ex:points:1":"〜ましょう: volitional / invitation (行きましょう)","grammar:7223:ex2:trans":"My favorite ramen shop is right here.","grammar:7223:ex2:structure":"お気に入りのラーメン店は＋ここです","grammar:7223:ex2:words:0:zh":"I","grammar:7223:ex2:words:0:note":"わたし","grammar:7223:ex2:words:0:pos":"pronoun","grammar:7223:ex2:words:1:zh":"'s","grammar:7223:ex2:words:1:pos":"particle","grammar:7223:ex2:words:2:zh":"favorite","grammar:7223:ex2:words:2:note":"おきにいり","grammar:7223:ex2:words:2:pos":"noun","grammar:7223:ex2:words:3:zh":"'s","grammar:7223:ex2:words:3:pos":"particle","grammar:7223:ex2:words:4:zh":"ramen shop","grammar:7223:ex2:words:4:note":"ラーメンてん","grammar:7223:ex2:words:4:pos":"noun","grammar:7223:ex2:words:5:zh":"(topic)","grammar:7223:ex2:words:5:pos":"particle","grammar:7223:ex2:words:6:zh":"here","grammar:7223:ex2:words:6:pos":"pronoun","grammar:7223:ex2:words:7:zh":"(assertion · polite)","grammar:7223:ex2:words:7:pos":"auxiliary verb","grammar:7223:ex2:points:0":"「お気に入りの」 = favorite (attributive modification)","grammar:7223:ex2:points:1":"AはBです: A is B (店は…ここです)","grammar:7223:ex3:trans":"This ramen is very delicious.","grammar:7223:ex3:structure":"このラーメンは とても＋美味しいです","grammar:7223:ex3:words:0:zh":"this (bowl of)","grammar:7223:ex3:words:0:pos":"pre-noun adjectival","grammar:7223:ex3:words:1:zh":"ramen","grammar:7223:ex3:words:1:pos":"noun","grammar:7223:ex3:words:2:zh":"(topic)","grammar:7223:ex3:words:2:pos":"particle","grammar:7223:ex3:words:3:zh":"extremely","grammar:7223:ex3:words:3:pos":"adverb","grammar:7223:ex3:words:4:zh":"delicious","grammar:7223:ex3:words:4:note":"おいしい","grammar:7223:ex3:words:4:pos":"adjective","grammar:7223:ex3:words:5:zh":"(polite)","grammar:7223:ex3:words:5:pos":"auxiliary verb","grammar:7223:ex3:points:0":"adverb 「とても」 = very (とても美味しい)","grammar:7223:ex3:points:1":"i-adjective ＋です: polite predicate (美味しいです)","grammar:7223:ex4:trans":"There are many kinds of ramen.","grammar:7223:ex4:structure":"ラーメンの種類はたくさん＋あります","grammar:7223:ex4:words:0:zh":"ramen","grammar:7223:ex4:words:0:pos":"noun","grammar:7223:ex4:words:1:zh":"'s","grammar:7223:ex4:words:1:pos":"particle","grammar:7223:ex4:words:2:zh":"kind","grammar:7223:ex4:words:2:note":"しゅるい","grammar:7223:ex4:words:2:pos":"noun","grammar:7223:ex4:words:3:zh":"(topic)","grammar:7223:ex4:words:3:pos":"particle","grammar:7223:ex4:words:4:zh":"a lot","grammar:7223:ex4:words:4:pos":"adverb","grammar:7223:ex4:words:5:zh":"there is / are","grammar:7223:ex4:words:5:pos":"verb","grammar:7223:ex4:points:0":"Adverb 「たくさん」 + ある: there are many (たくさんある)","grammar:7223:ex4:points:1":"の linking nouns: ラーメンの種類 (kinds of ramen)","grammar:7223:ex5:trans":"You can eat ramen until late at night.","grammar:7223:ex5:structure":"夜遅くまでラーメンを＋食べられます","grammar:7223:ex5:words:0:zh":"late at night","grammar:7223:ex5:words:0:note":"よるおそく","grammar:7223:ex5:words:0:pos":"noun","grammar:7223:ex5:words:1:zh":"until (end point in time)","grammar:7223:ex5:words:1:pos":"particle","grammar:7223:ex5:words:2:zh":"ramen","grammar:7223:ex5:words:2:pos":"noun","grammar:7223:ex5:words:3:zh":"(object marker)","grammar:7223:ex5:words:3:pos":"particle","grammar:7223:ex5:words:4:zh":"can eat (potential)","grammar:7223:ex5:words:4:note":"たべられます","grammar:7223:ex5:words:4:pos":"verb","grammar:7223:ex5:points:0":"〜まで: until〜 (夜遅くまで = until late at night)","grammar:7223:ex5:points:1":"Potential form: 食べる→食べられる (can eat)"},"7225":{"example:7225:exzh":"Please press the car's accelerator.","example:7225:exzh2":"Please ease off the accelerator a little.","example:7225:exzh3":"This car's accelerator is very sensitive.","example:7225:exzh4":"If you floor the accelerator, you can go fast.","example:7225:exzh5":"Adjusting the accelerator while driving is important."},"7228":{"example:7228:exzh":"He attends a boarding school.","example:7228:exzh2":"Living with a host family is fun.","example:7228:exzh3":"Japan's boarding culture is very old.","example:7228:exzh4":"Boarding students have a lot of rules.","example:7228:exzh5":"I made friends through boarding school life."},"7230":{"example:7230:exzh":"Romania is a beautiful country.","example:7230:exzh2":"Romanian food is very delicious.","example:7230:exzh3":"She has traveled to Romania before.","example:7230:exzh4":"Romanian culture is very diverse.","example:7230:exzh5":"Romanian is a difficult language."},"7231":{"example:7231:exzh":"Please write your name on this form.","example:7231:exzh2":"Please print the report on this form.","example:7231:exzh3":"There aren't enough forms, so please prepare another set.","example:7231:exzh4":"This form can be reused.","example:7231:exzh5":"There are many different types of forms."},"7232":{"example:7232:exzh":"He burned out from work.","example:7232:exzh2":"Please be careful about burnout syndrome.","example:7232:exzh3":"It's important to rest once in a while, so you don't burn out.","example:7232:exzh4":"I feel like I've been burning out lately.","example:7232:exzh5":"To avoid burning out, you need balance."},"7234":{"example:7234:exzh":"In this game, you often die instantly.","example:7234:exzh2":"Instant death is a matter of luck.","example:7234:exzh3":"People said there was a risk of instant death.","example:7234:exzh4":"I want to avoid instant death on this road.","example:7234:exzh5":"To avoid an instant-death situation, you need to be careful."},"7235":{"example:7235:exzh":"I bought a new bowl.","example:7235:exzh2":"This bowl is very big.","example:7235:exzh3":"Please put the salad in the bowl.","example:7235:exzh4":"The bowl broke.","example:7235:exzh5":"He eats cereal in a bowl every morning."},"7236":{"example:7236:exzh":"That slander has no basis.","example:7236:exzh2":"Being slandered is painful.","example:7236:exzh3":"Let's talk so we can resolve the slander problem.","example:7236:exzh4":"I saw her being slandered.","example:7236:exzh5":"Slander hurts people."},"7237":{"example:7237:exzh":"I like drinking beer.","example:7237:exzh2":"This beer is very tasty.","example:7237:exzh3":"Besides beer, there are many other drinks.","example:7237:exzh4":"I'm going to drink beer with a friend.","example:7237:exzh5":"Beer is the best when it's chilled.","grammar:7237:ex:trans":"I like drinking beer.","grammar:7237:ex:structure":"〜を飲むのが好きです","grammar:7237:ex:explain":"This sentence uses two key points at once. First, 「の」 turns the verb phrase 「ビールを飲む」 into a noun so it can be the object of liking. Second, the object of 「〜が好きです」 must take 「が」, not 「を」. The whole sentence forms the double-subject structure 「私は…が好きです」, where 「は」 handles the larger topic and 「が」 the smaller subject. To say you are bad at something or dislike it, use the same frame, for example 「飲むのが苦手です」.","grammar:7237:ex:words:0:zh":"I","grammar:7237:ex:words:0:note":"わたし","grammar:7237:ex:words:0:pos":"pronoun","grammar:7237:ex:words:1:zh":"(topic)","grammar:7237:ex:words:1:pos":"particle","grammar:7237:ex:words:2:zh":"beer","grammar:7237:ex:words:2:note":"loanword","grammar:7237:ex:words:2:pos":"noun","grammar:7237:ex:words:3:zh":"(object marker)","grammar:7237:ex:words:3:pos":"particle","grammar:7237:ex:words:4:zh":"to drink","grammar:7237:ex:words:4:note":"のむ","grammar:7237:ex:words:4:pos":"verb","grammar:7237:ex:words:5:zh":"(nominalizer)","grammar:7237:ex:words:5:pos":"particle","grammar:7237:ex:words:6:zh":"(object)","grammar:7237:ex:words:6:pos":"particle","grammar:7237:ex:words:7:zh":"to like","grammar:7237:ex:words:7:note":"すき","grammar:7237:ex:words:7:pos":"na-adjective","grammar:7237:ex:words:8:zh":"(polite form)","grammar:7237:ex:words:8:pos":"copula","grammar:7237:ex:points:0":"❗ビール: beer; ビールを飲む = to drink beer.","grammar:7237:ex:points:1":"ビールを飲む: to drink beer.","grammar:7237:ex2:trans":"This beer is really good.","grammar:7237:ex2:structure":"〜はとても美味しいです","grammar:7237:ex2:words:0:zh":"this","grammar:7237:ex2:words:0:pos":"pre-noun adjectival","grammar:7237:ex2:words:1:zh":"beer","grammar:7237:ex2:words:1:note":"loanword","grammar:7237:ex2:words:1:pos":"noun","grammar:7237:ex2:words:2:zh":"(topic)","grammar:7237:ex2:words:2:pos":"particle","grammar:7237:ex2:words:3:zh":"extremely","grammar:7237:ex2:words:3:pos":"adverb","grammar:7237:ex2:words:4:zh":"tasty","grammar:7237:ex2:words:4:note":"おいしい","grammar:7237:ex2:words:4:pos":"adjective","grammar:7237:ex2:words:5:zh":"(polite form)","grammar:7237:ex2:words:5:pos":"copula","grammar:7237:ex2:points:0":"❗このビール: this beer; 美味しい = delicious.","grammar:7237:ex2:points:1":"美味しいビール: delicious beer.","grammar:7237:ex3:trans":"Besides beer, there are all kinds of other drinks.","grammar:7237:ex3:structure":"〜以外にも〜があります","grammar:7237:ex3:words:0:zh":"beer","grammar:7237:ex3:words:0:note":"loanword","grammar:7237:ex3:words:0:pos":"noun","grammar:7237:ex3:words:1:zh":"other than / except","grammar:7237:ex3:words:1:note":"いがい","grammar:7237:ex3:words:1:pos":"noun","grammar:7237:ex3:words:2:zh":"(scope)","grammar:7237:ex3:words:2:pos":"particle","grammar:7237:ex3:words:3:zh":"also, too","grammar:7237:ex3:words:3:pos":"particle","grammar:7237:ex3:words:4:zh":"various","grammar:7237:ex3:words:4:note":"いろいろ","grammar:7237:ex3:words:4:pos":"na-adjective","grammar:7237:ex3:words:5:zh":"(attributive form)","grammar:7237:ex3:words:5:pos":"auxiliary verb","grammar:7237:ex3:words:6:zh":"drink","grammar:7237:ex3:words:6:note":"のみもの","grammar:7237:ex3:words:6:pos":"noun","grammar:7237:ex3:words:7:zh":"(nominative)","grammar:7237:ex3:words:7:pos":"particle","grammar:7237:ex3:words:8:zh":"there is / are","grammar:7237:ex3:words:8:pos":"verb","grammar:7237:ex3:points:0":"❗〜以外にも: besides … / in addition to …; 色々な = various kinds of.","grammar:7237:ex3:points:1":"以外にも: besides that, there is also …","grammar:7237:ex4:trans":"I'm going to go drink beer with a friend.","grammar:7237:ex4:structure":"〜を飲みに行きます","grammar:7237:ex4:words:0:zh":"friend","grammar:7237:ex4:words:0:note":"ともだち","grammar:7237:ex4:words:0:pos":"noun","grammar:7237:ex4:words:1:zh":"(object)","grammar:7237:ex4:words:1:pos":"particle","grammar:7237:ex4:words:2:zh":"beer","grammar:7237:ex4:words:2:note":"loanword","grammar:7237:ex4:words:2:pos":"noun","grammar:7237:ex4:words:3:zh":"(object marker)","grammar:7237:ex4:words:3:pos":"particle","grammar:7237:ex4:words:4:zh":"to drink","grammar:7237:ex4:words:4:note":"のみ","grammar:7237:ex4:words:4:pos":"noun","grammar:7237:ex4:words:5:zh":"(purpose)","grammar:7237:ex4:words:5:pos":"particle","grammar:7237:ex4:words:6:zh":"go","grammar:7237:ex4:words:6:pos":"verb","grammar:7237:ex4:points:0":"❗〜を飲みに行く: to go to drink … (masu-form of a verb + に).","grammar:7237:ex4:points:1":"飲みに行く: to go out to drink.","grammar:7237:ex5:trans":"Beer is the best when it's chilled.","grammar:7237:ex5:structure":"〜が冷えていると最高です","grammar:7237:ex5:words:0:zh":"beer","grammar:7237:ex5:words:0:note":"loanword","grammar:7237:ex5:words:0:pos":"noun","grammar:7237:ex5:words:1:zh":"(nominative)","grammar:7237:ex5:words:1:pos":"particle","grammar:7237:ex5:words:2:zh":"chilled","grammar:7237:ex5:words:2:note":"ひえている","grammar:7237:ex5:words:2:pos":"verb","grammar:7237:ex5:words:3:zh":"(as soon as…)","grammar:7237:ex5:words:3:pos":"particle","grammar:7237:ex5:words:4:zh":"the best","grammar:7237:ex5:words:4:note":"さいこう","grammar:7237:ex5:words:4:pos":"na-adjective","grammar:7237:ex5:words:5:zh":"(polite form)","grammar:7237:ex5:words:5:pos":"copula","grammar:7237:ex5:points:0":"❗冷えている: chilled (冷える, an intransitive verb describing a state); 〜と最高 = … and it's just the best.","grammar:7237:ex5:points:1":"冷えたビール: chilled beer.","exam:7237:zh":"My father is drinking cold beer that's yellow with white foam.","exam:7237:why":"A yellow drink with white foam on top is the typical look of 「ビール」. 「ウイスキー」 can also be yellow, but it usually doesn't have that kind of white foam."},"7238":{"example:7238:exzh":"He is pursuing the truth.","example:7238:exzh2":"Pursuing something is sometimes difficult.","example:7238:exzh3":"We need to pursue the issue.","example:7238:exzh4":"The pursuit regarding that incident is still ongoing.","example:7238:exzh5":"Pursuing the truth is important."},"7239":{"example:7239:exzh":"I felt a muscle cramp.","example:7239:exzh2":"After exercising, I sometimes get cramps.","example:7239:exzh3":"If a cramp happens, don't push yourself.","example:7239:exzh4":"He went to the hospital because of a cramp.","example:7239:exzh5":"If cramps happen often, please consult a doctor."},"7240":{"example:7240:exzh":"Can this door be opened?","example:7240:exzh2":"The door was shut by the strong wind.","example:7240:exzh3":"I replaced the old door with a new one.","example:7240:exzh4":"There's no one outside the door.","example:7240:exzh5":"Please knock on the door.","grammar:7240:ex:trans":"Can this door be opened?","grammar:7240:ex:structure":"この＋noun＋は＋開けられますか. 「開けられる」 is the potential form. 「戸」 = door.","grammar:7240:ex:explain":"The focus is the potential form. 「開ける」 is an ichidan (ru-) verb; the potential form replaces る with られる, giving 「開けられる」, and the polite question is 「開けられますか」, asking whether this door can be opened. Note that for ichidan verbs the potential and passive forms look identical — both are 「られる」 — so you can only tell from context. Young people often drop the ら in casual speech and say 「開けれる」, but formal usage still follows 「開けられる」.","grammar:7240:ex:words:0:zh":"this","grammar:7240:ex:words:0:pos":"pre-noun adjectival","grammar:7240:ex:words:1:zh":"door","grammar:7240:ex:words:1:note":"と","grammar:7240:ex:words:1:pos":"noun","grammar:7240:ex:words:2:zh":"(topic marker)","grammar:7240:ex:words:2:pos":"particle","grammar:7240:ex:words:3:zh":"can open","grammar:7240:ex:words:3:note":"potential form","grammar:7240:ex:words:3:pos":"verb","grammar:7240:ex:words:4:zh":"(question)","grammar:7240:ex:words:4:pos":"particle","grammar:7240:ex:points:0":"戸 (と): door, sliding door","grammar:7240:ex:points:1":"開けられる: can open (potential form of 開ける)","grammar:7240:ex2:trans":"The door was shut by the strong wind.","grammar:7240:ex2:structure":"名詞が＋強風で＋閉まった。 「で」 marks the cause, and 「閉まる」 = to shut (intransitive).","grammar:7240:ex2:words:0:zh":"door","grammar:7240:ex2:words:0:note":"と","grammar:7240:ex2:words:0:pos":"noun","grammar:7240:ex2:words:1:zh":"(nominative)","grammar:7240:ex2:words:1:pos":"particle","grammar:7240:ex2:words:2:zh":"strong wind / gale","grammar:7240:ex2:words:2:note":"きょうふう","grammar:7240:ex2:words:2:pos":"noun","grammar:7240:ex2:words:3:zh":"because","grammar:7240:ex2:words:3:note":"cause / reason","grammar:7240:ex2:words:3:pos":"particle","grammar:7240:ex2:words:4:zh":"closed","grammar:7240:ex2:words:4:note":"しまった","grammar:7240:ex2:words:4:pos":"verb","grammar:7240:ex2:points:0":"〜で: because of… (強風で = because of the strong wind)","grammar:7240:ex2:points:1":"閉まる: (intransitive verb) to close, to shut","grammar:7240:ex3:trans":"I replaced the old door with a new one.","grammar:7240:ex3:structure":"〔古い戸〕＋を＋〔新しくしました〕。 「い形容詞〜くする」 = to make… into…; 「新しくする」 = to renew, to replace with a new one.","grammar:7240:ex3:words:0:zh":"old","grammar:7240:ex3:words:0:note":"ふるい","grammar:7240:ex3:words:0:pos":"adjective","grammar:7240:ex3:words:1:zh":"door","grammar:7240:ex3:words:1:note":"と","grammar:7240:ex3:words:1:pos":"noun","grammar:7240:ex3:words:2:zh":"(object marker)","grammar:7240:ex3:words:2:pos":"particle","grammar:7240:ex3:words:3:zh":"making it new","grammar:7240:ex3:words:3:note":"あたらしく; adverbial form","grammar:7240:ex3:words:3:pos":"adjective","grammar:7240:ex3:words:4:zh":"did","grammar:7240:ex3:words:4:note":"〜くする","grammar:7240:ex3:words:4:pos":"verb","grammar:7240:ex3:points:0":"い形容詞〜くする: to make… (新しくする = to make new)","grammar:7240:ex3:points:1":"古い戸: old door","grammar:7240:ex4:trans":"There's no one outside the door.","grammar:7240:ex4:structure":"〔戸の外〕＋には＋誰も＋いない。 「誰も〜ない」 = nobody, not anyone…","grammar:7240:ex4:words:0:zh":"door","grammar:7240:ex4:words:0:note":"と","grammar:7240:ex4:words:0:pos":"noun","grammar:7240:ex4:words:1:zh":"'s","grammar:7240:ex4:words:1:pos":"particle","grammar:7240:ex4:words:2:zh":"outside","grammar:7240:ex4:words:2:note":"そと","grammar:7240:ex4:words:2:pos":"noun","grammar:7240:ex4:words:3:zh":"(location of existence＋emphasis)","grammar:7240:ex4:words:3:pos":"particle","grammar:7240:ex4:words:4:zh":"(not) anyone","grammar:7240:ex4:words:4:note":"だれも","grammar:7240:ex4:words:4:pos":"pronoun","grammar:7240:ex4:words:5:zh":"nobody","grammar:7240:ex4:words:5:note":"negative","grammar:7240:ex4:words:5:pos":"verb","grammar:7240:ex4:points:0":"誰も〜ない: nobody, not anyone (誰もいない = there is nobody)","grammar:7240:ex4:points:1":"戸の外: outside the door","grammar:7240:ex5:trans":"Please knock on the door.","grammar:7240:ex5:structure":"名詞を＋ノックしてください。 「戸をノックする」 = to knock on the door.","grammar:7240:ex5:words:0:zh":"door","grammar:7240:ex5:words:0:note":"と","grammar:7240:ex5:words:0:pos":"noun","grammar:7240:ex5:words:1:zh":"(object marker)","grammar:7240:ex5:words:1:pos":"particle","grammar:7240:ex5:words:2:zh":"knock","grammar:7240:ex5:words:2:note":"loanword verb knock; te-form","grammar:7240:ex5:words:2:pos":"verb","grammar:7240:ex5:words:3:zh":"please","grammar:7240:ex5:words:3:note":"〜てください","grammar:7240:ex5:words:3:pos":"verb","grammar:7240:ex5:points:0":"ノックする: to knock (on a door)","grammar:7240:ex5:points:1":"戸: door"},"7242":{"example:7242:exzh":"Rush hour is very crowded.","example:7242:exzh2":"I want to avoid going out during rush hour.","example:7242:exzh3":"The trains are crowded during rush hour.","example:7242:exzh4":"After rush hour, the station is a little quieter.","example:7242:exzh5":"Driving during rush hour is dangerous."},"7243":{"example:7243:exzh":"This product is effectively a good deal.","example:7243:exzh2":"The substantive problem has been solved.","example:7243:exzh3":"Substantial results are expected.","example:7243:exzh4":"It's an ideal with no substance behind it.","example:7243:exzh5":"It's important to consider substance."},"7244":{"example:7244:exzh":"I want to go to Disney this year.","example:7244:exzh2":"Disneyland is a fun place.","example:7244:exzh3":"I love Disney characters.","example:7244:exzh4":"Disney movies are wonderful.","example:7244:exzh5":"I'm collecting Disney merchandise."},"7246":{"example:7246:exzh":"He has a stubborn personality.","example:7246:exzh2":"Stubborn thinking needs improvement.","example:7246:exzh3":"A stubborn attitude sometimes causes problems.","example:7246:exzh4":"She stubbornly holds a different opinion.","example:7246:exzh5":"It's hard to talk with a stubborn person."},"7247":{"example:7247:exzh":"Smoke is coming out of the chimney.","example:7247:exzh2":"That chimney is old.","example:7247:exzh3":"The chimney needs cleaning.","example:7247:exzh4":"In winter, the chimney becomes especially important.","example:7247:exzh5":"I like houses that have a chimney."},"7248":{"example:7248:exzh":"You must not steal other people's things.","example:7248:exzh2":"The stolen item was found.","example:7248:exzh3":"Stealing is not allowed.","example:7248:exzh4":"There's no need to risk danger to steal.","example:7248:exzh5":"Stealing things is wrong.","grammar:7248:ex:trans":"You must not steal other people's things.","grammar:7248:ex:structure":"〔他のもの〕＋を＋〔盗んではいけません〕。 「〜てはいけない」 = must not…","grammar:7248:ex:explain":"The core is 「verb te-form ＋ はいけない」, which expresses prohibition. It is fairly strong and mostly used for rules or warnings. The 「は」 here is not a topic marker but adds contrastive emphasis, and it attaches to the te-form as a fixed expression; in casual speech it contracts to 「盗んじゃいけない」. The te-form of 「盗む」 undergoes nasal sound change because it ends in む, giving 「盗んで」. The polite 「いけません」 is slightly more courteous than the plain 「いけない」.","grammar:7248:ex:words:0:zh":"other people","grammar:7248:ex:words:0:note":"ほか","grammar:7248:ex:words:0:pos":"noun","grammar:7248:ex:words:1:zh":"'s","grammar:7248:ex:words:1:pos":"particle","grammar:7248:ex:words:2:zh":"things","grammar:7248:ex:words:2:pos":"noun","grammar:7248:ex:words:3:zh":"(object marker)","grammar:7248:ex:words:3:pos":"particle","grammar:7248:ex:words:4:zh":"to steal","grammar:7248:ex:words:4:note":"ぬすんで; te-form","grammar:7248:ex:words:4:pos":"verb","grammar:7248:ex:words:5:zh":"(emphasis)","grammar:7248:ex:words:5:pos":"particle","grammar:7248:ex:words:6:zh":"no good","grammar:7248:ex:words:6:note":"〜てはいけない","grammar:7248:ex:words:6:pos":"Expression","grammar:7248:ex:points:0":"〜てはいけません: must not… (prohibition)","grammar:7248:ex:points:1":"盗む: to steal","grammar:7248:ex2:trans":"The stolen item was found.","grammar:7248:ex2:structure":"〔盗まれた〕＋物＋が＋見つかりました。 「盗まれた」 modifies 「物」, and 「見つかる」 = to be found (intransitive).","grammar:7248:ex2:words:0:zh":"stolen","grammar:7248:ex2:words:0:note":"passive ta-form modifying","grammar:7248:ex2:words:0:pos":"verb","grammar:7248:ex2:words:1:zh":"things","grammar:7248:ex2:words:1:note":"もの","grammar:7248:ex2:words:1:pos":"noun","grammar:7248:ex2:words:2:zh":"(nominative)","grammar:7248:ex2:words:2:pos":"particle","grammar:7248:ex2:words:3:zh":"was found","grammar:7248:ex2:words:3:note":"みつかりました","grammar:7248:ex2:words:3:pos":"verb","grammar:7248:ex2:points:0":"盗まれる: to be stolen (passive of 盗む)","grammar:7248:ex2:points:1":"見つかる: (intransitive verb) to be found","grammar:7248:ex3:trans":"Stealing is not allowed.","grammar:7248:ex3:structure":"〔盗む＋こと〕＋は＋許されません。 「許される」 = to be permitted (passive); the negative means it is not allowed.","grammar:7248:ex3:words:0:zh":"to steal","grammar:7248:ex3:words:0:note":"ぬすむ; dictionary form","grammar:7248:ex3:words:0:pos":"verb","grammar:7248:ex3:words:1:zh":"(nominalizer)","grammar:7248:ex3:words:1:pos":"noun","grammar:7248:ex3:words:2:zh":"(topic marker)","grammar:7248:ex3:words:2:pos":"particle","grammar:7248:ex3:words:3:zh":"is not allowed","grammar:7248:ex3:words:3:note":"ゆるされません; negative passive","grammar:7248:ex3:words:3:pos":"verb","grammar:7248:ex3:points:0":"許される: to be permitted (passive of 許す)","grammar:7248:ex3:points:1":"verb＋こと: the act of…","grammar:7248:ex4:trans":"There's no need to take the risk of stealing.","grammar:7248:ex4:structure":"〜て＋verb in dictionary form＋必要はない","grammar:7248:ex4:explain":"「危険を冒して」 links to 「盗む」 with the te-form, meaning to steal while taking on the risk. The whole phrase 「危険を冒して盗む」 modifies the noun 「必要」. 「必要はない」 negates the necessity of doing so; here 「ない」 expresses non-existence and is an i-adjective.","grammar:7248:ex4:words:0:zh":"danger, risk","grammar:7248:ex4:words:0:note":"きけん","grammar:7248:ex4:words:0:pos":"noun","grammar:7248:ex4:words:1:zh":"(object)","grammar:7248:ex4:words:1:pos":"particle","grammar:7248:ex4:words:2:zh":"to risk, to take on","grammar:7248:ex4:words:2:note":"おかし","grammar:7248:ex4:words:2:pos":"verb","grammar:7248:ex4:words:3:zh":"(links actions, showing accompanying circumstances)","grammar:7248:ex4:words:3:pos":"particle","grammar:7248:ex4:words:4:zh":"to steal","grammar:7248:ex4:words:4:note":"ぬすむ","grammar:7248:ex4:words:4:pos":"verb","grammar:7248:ex4:words:5:zh":"necessary","grammar:7248:ex4:words:5:note":"ひつよう","grammar:7248:ex4:words:5:pos":"noun","grammar:7248:ex4:words:6:zh":"(raises a topic, with emphasis)","grammar:7248:ex4:words:6:pos":"particle","grammar:7248:ex4:words:7:zh":"don't have","grammar:7248:ex4:words:7:pos":"i-adjective","grammar:7248:ex4:points:0":"「危険を冒す」 is a fixed expression meaning to take a risk or bear the risk.","grammar:7248:ex4:points:1":"「verb dictionary form＋必要はない」 means there is no need to do something—it does not mean it is forbidden.","grammar:7248:ex5:trans":"Stealing things is a bad thing to do.","grammar:7248:ex5:structure":"verb dictionary form＋ことは、悪いことです","grammar:7248:ex5:explain":"「物を盗む」 means to steal something, and 「を」 marks what is being stolen. Adding 「こと」 turns the whole phrase into \"the act of stealing,\" which 「は」 then brings up as the topic for comment. 「悪いことです」 means it is a bad thing or act—the two uses of 「こと」 play different roles in the sentence.","grammar:7248:ex5:words:0:zh":"things","grammar:7248:ex5:words:0:note":"もの","grammar:7248:ex5:words:0:pos":"noun","grammar:7248:ex5:words:1:zh":"(object)","grammar:7248:ex5:words:1:pos":"particle","grammar:7248:ex5:words:2:zh":"to steal","grammar:7248:ex5:words:2:note":"ぬすむ","grammar:7248:ex5:words:2:pos":"verb","grammar:7248:ex5:words:3:zh":"(nominalizes the action)","grammar:7248:ex5:words:3:pos":"noun","grammar:7248:ex5:words:4:zh":"(introduces the topic)","grammar:7248:ex5:words:4:pos":"particle","grammar:7248:ex5:words:5:zh":"bad","grammar:7248:ex5:words:5:note":"わるい","grammar:7248:ex5:words:5:pos":"i-adjective","grammar:7248:ex5:words:6:zh":"thing, act","grammar:7248:ex5:words:6:pos":"noun","grammar:7248:ex5:words:7:zh":"(states it politely)","grammar:7248:ex5:words:7:pos":"auxiliary verb","grammar:7248:ex5:points:0":"The first 「こと」 nominalizes 「物を盗む」, making the whole action the topic.","grammar:7248:ex5:points:1":"The second 「こと」 means a thing or act, and is modified by 「悪い」."},"7249":{"example:7249:exzh":"I bought a picture book for my child.","example:7249:exzh2":"Picture books are fun to read.","example:7249:exzh3":"Let's read a picture book together.","example:7249:exzh4":"Picture books have beautiful illustrations.","example:7249:exzh5":"Picture books nurture a child's imagination."},"7250":{"example:7250:exzh":"He's perfectly healthy.","example:7250:exzh2":"This lively dog runs around a lot.","example:7250:exzh3":"My mother is living well.","example:7250:exzh4":"It's important to stay healthy.","example:7250:exzh5":"It's fun talking with someone who's in good health."},"7251":{"example:7251:exzh":"We decided to split it equally among everyone.","example:7251:exzh2":"We'll split the income equally.","example:7251:exzh3":"We decided on the rules for splitting it equally.","example:7251:exzh4":"He split the prize money equally.","example:7251:exzh5":"After splitting it equally, everyone became happy."},"7252":{"example:7252:exzh":"Raising children is hard work.","example:7252:exzh2":"She is devoting herself to raising her child.","example:7252:exzh3":"Raising children takes love.","example:7252:exzh4":"Let's talk about how things are with child-rearing these days.","example:7252:exzh5":"There are also times when raising children is fun."},"7253":{"example:7253:exzh":"She has a fiancé.","example:7253:exzh2":"He is my fiancé.","example:7253:exzh3":"I'm enjoying my relationship with my fiancé.","example:7253:exzh4":"I'm preparing to marry my fiancé.","example:7253:exzh5":"My fiancé is a gentle person."},"7254":{"example:7254:exzh":"I bought a new lens.","example:7254:exzh2":"This lens can take beautiful photos.","example:7254:exzh3":"Clean the camera lens.","example:7254:exzh4":"I replaced the lens.","example:7254:exzh5":"The lens is an important part."},"7255":{"example:7255:exzh":"That outfit is too flashy—it's a bit too much, right?","example:7255:exzh2":"I added too much sugar, so the sweetness became too much.","example:7255:exzh3":"I think that makeup is a bit too much.","example:7255:exzh4":"I was told that my explanation was too long and too much.","example:7255:exzh5":"I'm careful not to let my makeup become too much."},"7256":{"example:7256:exzh":"He is a selfish child.","example:7256:exzh2":"You mustn't say selfish things.","example:7256:exzh3":"She is sometimes selfish.","example:7256:exzh4":"Please don't be selfish.","example:7256:exzh5":"I reflect on my selfish behavior."},"7257":{"example:7257:exzh":"This sugar is refined.","example:7257:exzh2":"That oil uses a refined product.","example:7257:exzh3":"Drinking refined water is important.","example:7257:exzh4":"Refined foods are sometimes bad for your health.","example:7257:exzh5":"This refining process is very important."},"7258":{"example:7258:exzh":"I picked up a package at the post office.","example:7258:exzh2":"He is waiting to receive the money.","example:7258:exzh3":"A procedure is required to receive it.","example:7258:exzh4":"I received a receipt.","example:7258:exzh5":"Don't forget to confirm that the package has been received."},"7259":{"example:7259:exzh":"We need to shrink the project budget.","example:7259:exzh2":"I shrank the image and printed it.","example:7259:exzh3":"A reduction in taxes was announced.","example:7259:exzh4":"This policy will reduce expenses.","example:7259:exzh5":"I'm looking for a way to shorten the time."},"7260":{"example:7260:exzh":"He lives in a large mansion.","example:7260:exzh2":"This mansion is a historic building.","example:7260:exzh3":"The mansion she lives in is beautiful.","example:7260:exzh4":"Beautiful flowers are blooming in the mansion's garden.","example:7260:exzh5":"There is a tall fence around the mansion."},"7261":{"example:7261:exzh":"The two of them are arguing.","example:7261:exzh2":"Arguments are sometimes unnecessary.","example:7261:exzh3":"He wants to avoid an argument.","example:7261:exzh4":"Arguing is exhausting.","example:7261:exzh5":"An argument with a friend is sad."},"7262":{"example:7262:exzh":"Today I'm eating flounder sashimi.","example:7262:exzh2":"Flounder is often used in Japanese cooking.","example:7262:exzh3":"Fresh flounder is very tasty.","example:7262:exzh4":"Fried flounder is popular.","example:7262:exzh5":"I bought flounder at the market."},"7264":{"example:7264:exzh":"I attended a shareholders' meeting.","example:7264:exzh2":"He is a shareholder of a large company.","example:7264:exzh3":"It is necessary to protect shareholders' rights.","example:7264:exzh4":"A new shareholder joined the company.","example:7264:exzh5":"The shareholders are hoping for profit."},"7265":{"example:7265:exzh":"I took a walk in the plum grove.","example:7265:exzh2":"The plum grove is very beautiful in spring.","example:7265:exzh3":"There are many birds in the plum grove.","example:7265:exzh4":"He took photos in the plum grove.","example:7265:exzh5":"I like the scent of the plum grove."},"7266":{"example:7266:exzh":"His smile is a sign of happiness.","example:7266:exzh2":"You could say that work is a sign of his effort.","example:7266:exzh3":"This phenomenon is a sign of social change.","example:7266:exzh4":"Her attitude is a sign of indifference.","example:7266:exzh5":"Her face shows all kinds of emotions."},"7267":{"example:7267:exzh":"Looking back at history, we can learn many lessons.","example:7267:exzh2":"He went back to his boyhood and got lost in memories.","example:7267:exzh3":"This record goes back to 1980.","example:7267:exzh4":"Let's talk about the past.","example:7267:exzh5":"Looking back, meeting him was a long time ago."},"7268":{"example:7268:exzh":"His plan collapsed.","example:7268:exzh2":"There is a risk that the economy will collapse.","example:7268:exzh3":"That project is facing the danger of collapse.","example:7268:exzh4":"The castle fell to the enemy.","example:7268:exzh5":"His trust crumbled after a single failure."},"7269":{"example:7269:exzh":"He is a strict father.","example:7269:exzh2":"The rules at this school are strict.","example:7269:exzh3":"You have to follow strict rules.","example:7269:exzh4":"Her management style is known for being strict.","example:7269:exzh5":"Learning from a strict teacher is a good experience."},"7270":{"example:7270:exzh":"I like dishes made with octopus.","example:7270:exzh2":"This octopus is fresh.","example:7270:exzh3":"Octopus sashimi is delicious.","example:7270:exzh4":"Takoyaki is a very popular dish.","example:7270:exzh5":"The octopus is one of the ocean's creatures."},"7271":{"example:7271:exzh":"Tractors are used on farms.","example:7271:exzh2":"The fields are plowed with a tractor.","example:7271:exzh3":"A tractor drives through the rice paddy.","example:7271:exzh4":"He is good at driving a tractor.","example:7271:exzh5":"It is the time of year when tractors are needed."},"7272":{"example:7272:exzh":"He was arrested for a hit-and-run.","example:7272:exzh2":"Hit-and-run incidents are increasing.","example:7272:exzh3":"The police are looking for witnesses to the hit-and-run.","example:7272:exzh4":"Hit-and-runs carry severe penalties.","example:7272:exzh5":"The victim was involved in a hit-and-run."},"7273":{"example:7273:exzh":"Coercion is not acceptable.","example:7273:exzh2":"She is a victim of coercion.","example:7273:exzh3":"Coercive behavior is prohibited by law.","example:7273:exzh4":"I was being coerced.","example:7273:exzh5":"Coercion can become the source of problems."},"7274":{"example:7274:exzh":"He recovered from rock bottom.","example:7274:exzh2":"I understand the feeling of being at rock bottom.","example:7274:exzh3":"Bouncing back from rock bottom is important.","example:7274:exzh4":"She has been through rock bottom.","example:7274:exzh5":"It takes effort to climb up from rock bottom."},"7275":{"example:7275:exzh":"I went to a general store.","example:7275:exzh2":"She likes collecting knick-knacks.","example:7275:exzh3":"I always want knick-knacks.","example:7275:exzh4":"There are all kinds of knick-knacks.","example:7275:exzh5":"I found something interesting at a general store."},"7276":{"example:7276:exzh":"I bought a swimsuit in summer.","example:7276:exzh2":"She went to the beach in a swimsuit.","example:7276:exzh3":"Where can I buy a swimsuit?","example:7276:exzh4":"I forgot to bring a swimsuit.","example:7276:exzh5":"I got into the pool wearing a swimsuit."},"7277":{"example:7277:exzh":"Please write in the field on the form.","example:7277:exzh2":"He wrote a name in the field.","example:7277:exzh3":"The newspaper's columns are easy to read.","example:7277:exzh4":"You must not leave any blank fields.","example:7277:exzh5":"Please fill in each field."},"7278":{"example:7278:exzh":"I got a receipt.","example:7278:exzh2":"I'm keeping the receipt.","example:7278:exzh3":"Please check the receipt.","example:7278:exzh4":"Is this receipt necessary?","example:7278:exzh5":"The receipt is torn."},"7279":{"example:7279:exzh":"He tried not to leave any trace of that place.","example:7279:exzh2":"It disappeared completely, leaving no trace.","example:7279:exzh3":"Tracking down the traces of that incident is difficult.","example:7279:exzh4":"Her smile comes back to me even now, without a trace.","example:7279:exzh5":"They left without leaving a trace."},"7280":{"example:7280:exzh":"I like sushi.","example:7280:exzh2":"He likes movies.","example:7280:exzh3":"She likes music.","example:7280:exzh4":"Do you like dogs?","example:7280:exzh5":"I like traveling.","grammar:7280:ex:trans":"I like sushi.","grammar:7280:ex:structure":"〜は〜が好きです","grammar:7280:ex:explain":"This is the classic double-subject sentence with 「〜は〜が好きです」. 「私は」 uses 「は」 to frame the broad topic, and 「寿司が」 uses 「が」 to mark the object of liking. Saying I like sushi in Chinese looks like a verb plus object, but Japanese 「好き」 is a na-adjective, so its object can only take 「が」; writing 「寿司を好きです」 is a common mistake. To emphasize it more, you can switch to 「大好きです」.","grammar:7280:ex:words:0:zh":"I","grammar:7280:ex:words:0:note":"わたし","grammar:7280:ex:words:0:pos":"pronoun","grammar:7280:ex:words:1:zh":"(topic)","grammar:7280:ex:words:1:pos":"particle","grammar:7280:ex:words:2:zh":"sushi","grammar:7280:ex:words:2:note":"すし","grammar:7280:ex:words:2:pos":"noun","grammar:7280:ex:words:3:zh":"(object of liking)","grammar:7280:ex:words:3:pos":"particle","grammar:7280:ex:words:4:zh":"to like","grammar:7280:ex:words:4:note":"すき","grammar:7280:ex:words:4:pos":"na-adjective","grammar:7280:ex:words:5:zh":"(polite form)","grammar:7280:ex:words:5:pos":"copula","grammar:7280:ex:points:0":"❗〜が好き: like … (the object of liking takes が, not を).","grammar:7280:ex:points:1":"私は〜が好き: (I) like …","grammar:7280:ex2:trans":"He likes movies.","grammar:7280:ex2:structure":"〜が好きです","grammar:7280:ex2:words:0:zh":"he","grammar:7280:ex2:words:0:note":"かれ","grammar:7280:ex2:words:0:pos":"pronoun","grammar:7280:ex2:words:1:zh":"(topic)","grammar:7280:ex2:words:1:pos":"particle","grammar:7280:ex2:words:2:zh":"movie","grammar:7280:ex2:words:2:note":"えいが","grammar:7280:ex2:words:2:pos":"noun","grammar:7280:ex2:words:3:zh":"(object)","grammar:7280:ex2:words:3:pos":"particle","grammar:7280:ex2:words:4:zh":"to like","grammar:7280:ex2:words:4:note":"すき","grammar:7280:ex2:words:4:pos":"na-adjective","grammar:7280:ex2:words:5:zh":"(polite form)","grammar:7280:ex2:words:5:pos":"copula","grammar:7280:ex2:points:0":"映画が好き: likes movies.","grammar:7280:ex2:points:1":"が marks the object of liking.","grammar:7280:ex3:trans":"She likes music.","grammar:7280:ex3:structure":"〜が好きです","grammar:7280:ex3:words:0:zh":"she","grammar:7280:ex3:words:0:note":"かのじょ","grammar:7280:ex3:words:0:pos":"pronoun","grammar:7280:ex3:words:1:zh":"(topic)","grammar:7280:ex3:words:1:pos":"particle","grammar:7280:ex3:words:2:zh":"music","grammar:7280:ex3:words:2:note":"おんがく","grammar:7280:ex3:words:2:pos":"noun","grammar:7280:ex3:words:3:zh":"(object)","grammar:7280:ex3:words:3:pos":"particle","grammar:7280:ex3:words:4:zh":"to like","grammar:7280:ex3:words:4:note":"すき","grammar:7280:ex3:words:4:pos":"na-adjective","grammar:7280:ex3:words:5:zh":"(polite form)","grammar:7280:ex3:words:5:pos":"copula","grammar:7280:ex3:points:0":"音楽が好き: to like music.","grammar:7280:ex3:points:1":"彼女は: she (topic).","grammar:7280:ex4:trans":"Do you like dogs?","grammar:7280:ex4:structure":"〜が好きですか","grammar:7280:ex4:words:0:zh":"dog","grammar:7280:ex4:words:0:note":"いぬ","grammar:7280:ex4:words:0:pos":"noun","grammar:7280:ex4:words:1:zh":"(object)","grammar:7280:ex4:words:1:pos":"particle","grammar:7280:ex4:words:2:zh":"to like","grammar:7280:ex4:words:2:note":"すき","grammar:7280:ex4:words:2:pos":"na-adjective","grammar:7280:ex4:words:3:zh":"(polite form)","grammar:7280:ex4:words:3:pos":"copula","grammar:7280:ex4:words:4:zh":"(question)","grammar:7280:ex4:words:4:pos":"particle","grammar:7280:ex4:points:0":"犬が好きですか: do you like dogs?","grammar:7280:ex4:points:1":"が＋好き: the object of liking.","grammar:7280:ex5:trans":"I like traveling.","grammar:7280:ex5:structure":"〜は〜が好きです","grammar:7280:ex5:words:0:zh":"I","grammar:7280:ex5:words:0:note":"わたし","grammar:7280:ex5:words:0:pos":"pronoun","grammar:7280:ex5:words:1:zh":"(topic)","grammar:7280:ex5:words:1:pos":"particle","grammar:7280:ex5:words:2:zh":"travel / trip","grammar:7280:ex5:words:2:note":"りょこう","grammar:7280:ex5:words:2:pos":"noun","grammar:7280:ex5:words:3:zh":"(object)","grammar:7280:ex5:words:3:pos":"particle","grammar:7280:ex5:words:4:zh":"to like","grammar:7280:ex5:words:4:note":"すき","grammar:7280:ex5:words:4:pos":"na-adjective","grammar:7280:ex5:words:5:zh":"(polite form)","grammar:7280:ex5:words:5:pos":"copula","grammar:7280:ex5:points:0":"旅行が好き: to like traveling.","grammar:7280:ex5:points:1":"私は〜が好き: I like …","exam:7280:zh":"I love dogs, so I'm really happy when I play with them.","exam:7280:why":"「好き」 means to like, which fits the reason playing with dogs makes me happy. 「上手」 means to be good at, and you can't use 「犬が上手」 to say you like dogs."},"7281":{"example:7281:exzh":"What's inside this box?","example:7281:exzh2":"I was curious about what was inside, so I opened it up.","example:7281:exzh3":"The contents of this dish are very rich.","example:7281:exzh4":"I opened the bag to check the contents.","example:7281:exzh5":"If what is inside is good, it gets a lot of word of mouth."},"7282":{"example:7282:exzh":"A person wearing a mask appeared.","example:7282:exzh2":"He is an anonymous author.","example:7282:exzh3":"This festival has a tradition of wearing masks.","example:7282:exzh4":"The masked person's true identity was finally revealed.","example:7282:exzh5":"It's difficult to talk while wearing a mask."},"7283":{"example:7283:exzh":"You have to pick up dog poop.","example:7283:exzh2":"The baby pooped.","example:7283:exzh3":"Poop stinks, doesn't it?","example:7283:exzh4":"Cat poop has to be dealt with too.","example:7283:exzh5":"Please don't leave poop in the park."},"7284":{"example:7284:exzh":"He changed jobs to find a new one.","example:7284:exzh2":"You need to think carefully when changing jobs.","example:7284:exzh3":"Please explain clearly why you are changing jobs.","example:7284:exzh4":"Using a job-change agency is convenient.","example:7284:exzh5":"After deciding to change jobs, she took action right away."},"7285":{"example:7285:exzh":"I really love shabu-shabu.","example:7285:exzh2":"Today I'm going to eat shabu-shabu with a friend.","example:7285:exzh3":"Shabu-shabu is one of Japan's most popular dishes.","example:7285:exzh4":"It's fun to swish the meat in the pot.","example:7285:exzh5":"I made sauce for shabu-shabu."},"7286":{"example:7286:exzh":"Time passes quickly.","example:7286:exzh2":"A lot has changed over these years.","example:7286:exzh3":"We grow as the years pile up.","example:7286:exzh4":"As the years went by, the memories grew in number.","example:7286:exzh5":"I like music that lets you feel the passage of time."},"7287":{"example:7287:exzh":"I live in Taiwan.","example:7287:exzh2":"Taiwanese food is delicious.","example:7287:exzh3":"Taiwan is a beautiful island.","example:7287:exzh4":"I want to learn about Taiwanese culture.","example:7287:exzh5":"I'm planning to travel to Taiwan."},"7288":{"example:7288:exzh":"Beef is very nutritious.","example:7288:exzh2":"I like beef curry.","example:7288:exzh3":"I'm good at making beef dishes.","example:7288:exzh4":"Eating beef gives me strength.","example:7288:exzh5":"I made a stir-fry of beef and vegetables."},"7289":{"example:7289:exzh":"The symptoms of that disease appeared.","example:7289:exzh2":"It's important to diagnose the symptoms correctly.","example:7289:exzh3":"This symptom might be caused by stress.","example:7289:exzh4":"Understanding the symptoms is the first step in treatment.","example:7289:exzh5":"His symptoms are getting worse day by day."},"7290":{"example:7290:exzh":"My dad is kind.","example:7290:exzh2":"I like playing with my dad.","example:7290:exzh3":"His dad has a busy job.","example:7290:exzh4":"Dad is good at cooking.","example:7290:exzh5":"My dad always helps me.","grammar:7290:ex:trans":"My dad is kind.","grammar:7290:ex:structure":"〜のおとうさんは〜です","grammar:7290:ex:explain":"This is an 「AはBです」 descriptive sentence; the predicate is the i-adjective 「優しい」, and 「です」 is added only for politeness. Grammatically an i-adjective can end a sentence on its own, so in casual speech you just say 「優しい」. 「僕」 is a fairly casual first-person pronoun used by men. Note also that when talking about your own father to others, Japanese usually says 「父」; 「おとうさん」 is used for someone else's father or within the family, so this sentence sounds casual and slightly childlike.","grammar:7290:ex:words:0:zh":"I","grammar:7290:ex:words:0:note":"ぼく","grammar:7290:ex:words:0:pos":"pronoun","grammar:7290:ex:words:1:zh":"'s","grammar:7290:ex:words:1:pos":"particle","grammar:7290:ex:words:2:zh":"dad","grammar:7290:ex:words:2:pos":"noun","grammar:7290:ex:words:3:zh":"(topic)","grammar:7290:ex:words:3:pos":"particle","grammar:7290:ex:words:4:zh":"kind","grammar:7290:ex:words:4:note":"やさしい","grammar:7290:ex:words:4:pos":"adjective","grammar:7290:ex:words:5:zh":"(polite form)","grammar:7290:ex:words:5:pos":"copula","grammar:7290:ex:points:0":"❗お父さん（おとうさん）: dad (when addressing him or referring to someone else's father); for your own father use the humble 「父（ちち）」.","grammar:7290:ex:points:1":"僕: I (male).","grammar:7290:ex2:trans":"I like playing with my dad.","grammar:7290:ex2:structure":"〜のが好きです","grammar:7290:ex2:words:0:zh":"dad","grammar:7290:ex2:words:0:pos":"noun","grammar:7290:ex2:words:1:zh":"with","grammar:7290:ex2:words:1:pos":"particle","grammar:7290:ex2:words:2:zh":"together","grammar:7290:ex2:words:2:note":"いっしょに","grammar:7290:ex2:words:2:pos":"adverb","grammar:7290:ex2:words:3:zh":"hang out","grammar:7290:ex2:words:3:note":"あそぶ","grammar:7290:ex2:words:3:pos":"verb","grammar:7290:ex2:words:4:zh":"(nominalizer)","grammar:7290:ex2:words:4:pos":"particle","grammar:7290:ex2:words:5:zh":"(object)","grammar:7290:ex2:words:5:pos":"particle","grammar:7290:ex2:words:6:zh":"to like","grammar:7290:ex2:words:6:note":"すき","grammar:7290:ex2:words:6:pos":"na-adjective","grammar:7290:ex2:words:7:zh":"(polite form)","grammar:7290:ex2:words:7:pos":"copula","grammar:7290:ex2:points:0":"おとうさんと一緒に: together with dad.","grammar:7290:ex2:points:1":"〜のが好き: to like doing…","grammar:7290:ex3:trans":"His dad has a busy job.","grammar:7290:ex3:structure":"〜は〜仕事をしています","grammar:7290:ex3:words:0:zh":"he","grammar:7290:ex3:words:0:note":"かれ","grammar:7290:ex3:words:0:pos":"pronoun","grammar:7290:ex3:words:1:zh":"'s","grammar:7290:ex3:words:1:pos":"particle","grammar:7290:ex3:words:2:zh":"dad","grammar:7290:ex3:words:2:pos":"noun","grammar:7290:ex3:words:3:zh":"(topic)","grammar:7290:ex3:words:3:pos":"particle","grammar:7290:ex3:words:4:zh":"busy","grammar:7290:ex3:words:4:note":"いそがしい","grammar:7290:ex3:words:4:pos":"adjective","grammar:7290:ex3:words:5:zh":"work","grammar:7290:ex3:words:5:note":"しごと","grammar:7290:ex3:words:5:pos":"noun","grammar:7290:ex3:words:6:zh":"(object marker)","grammar:7290:ex3:words:6:pos":"particle","grammar:7290:ex3:words:7:zh":"is doing","grammar:7290:ex3:words:7:pos":"verb","grammar:7290:ex3:points:0":"忙しい仕事: a busy job.","grammar:7290:ex3:points:1":"仕事をする: work.","grammar:7290:ex4:trans":"Dad is good at cooking.","grammar:7290:ex4:structure":"〜が得意です","grammar:7290:ex4:words:0:zh":"dad","grammar:7290:ex4:words:0:pos":"noun","grammar:7290:ex4:words:1:zh":"(topic)","grammar:7290:ex4:words:1:pos":"particle","grammar:7290:ex4:words:2:zh":"dish / cuisine","grammar:7290:ex4:words:2:note":"りょうり","grammar:7290:ex4:words:2:pos":"noun","grammar:7290:ex4:words:3:zh":"(object)","grammar:7290:ex4:words:3:pos":"particle","grammar:7290:ex4:words:4:zh":"good at","grammar:7290:ex4:words:4:note":"とくい","grammar:7290:ex4:words:4:pos":"na-adjective","grammar:7290:ex4:words:5:zh":"(polite form)","grammar:7290:ex4:words:5:pos":"copula","grammar:7290:ex4:points:0":"With 得意, the target takes が.","grammar:7290:ex4:points:1":"料理が得意: good at cooking.","grammar:7290:ex5:trans":"My dad always helps me.","grammar:7290:ex5:structure":"いつも〜てくれます","grammar:7290:ex5:words:0:zh":"I","grammar:7290:ex5:words:0:note":"わたし","grammar:7290:ex5:words:0:pos":"pronoun","grammar:7290:ex5:words:1:zh":"'s","grammar:7290:ex5:words:1:pos":"particle","grammar:7290:ex5:words:2:zh":"dad","grammar:7290:ex5:words:2:pos":"noun","grammar:7290:ex5:words:3:zh":"(topic)","grammar:7290:ex5:words:3:pos":"particle","grammar:7290:ex5:words:4:zh":"always","grammar:7290:ex5:words:4:pos":"adverb","grammar:7290:ex5:words:5:zh":"help","grammar:7290:ex5:words:5:note":"たすけて","grammar:7290:ex5:words:5:pos":"verb","grammar:7290:ex5:words:6:zh":"makes (for me)","grammar:7290:ex5:words:6:pos":"auxiliary verb","grammar:7290:ex5:points:0":"❗〜てくれる: (someone) does … for me (助けてくれる = helps me).","grammar:7290:ex5:points:1":"いつも: always.","exam:7290:zh":"Kenta, your mother's husband is your father, right?","exam:7290:why":"In this family relationship, your mother's husband is 「お父さん」. 「おじいさん」 is your grandfather, one generation apart."},"7293":{"example:7293:exzh":"Something bad might happen.","example:7293:exzh2":"A major accident happened.","example:7293:exzh3":"There's no telling when an earthquake will happen.","example:7293:exzh4":"Something mysterious happened.","example:7293:exzh5":"I hope something fun happens.","grammar:7293:ex:trans":"Something bad might happen.","grammar:7293:ex:structure":"〜が起こるかもしれません","grammar:7293:ex:explain":"The pattern 「dictionary-form verb + かもしれません」 expresses speculation, with a probability of roughly fifty percent; it sounds less certain than 「〜でしょう」. The plain form is 「かもしれない」, and in casual speech it can be shortened to 「かも」. 「何か」 is an indefinite pronoun meaning some unspecified thing, and the 「悪いこと」 that follows it uses an i-adjective in its direct modifying form before the formal noun 「こと」. 「起こる」 is an intransitive verb: the event happens on its own, so the subject takes 「が」.","grammar:7293:ex:words:0:zh":"what","grammar:7293:ex:words:0:note":"なにか","grammar:7293:ex:words:0:pos":"pronoun","grammar:7293:ex:words:1:zh":"bad / not good","grammar:7293:ex:words:1:note":"わるい","grammar:7293:ex:words:1:pos":"adjective","grammar:7293:ex:words:2:zh":"thing / matter","grammar:7293:ex:words:2:pos":"noun","grammar:7293:ex:words:3:zh":"(nominative)","grammar:7293:ex:words:3:pos":"particle","grammar:7293:ex:words:4:zh":"happened","grammar:7293:ex:words:4:note":"おこる","grammar:7293:ex:words:4:pos":"verb","grammar:7293:ex:words:5:zh":"possible","grammar:7293:ex:words:5:pos":"set phrase","grammar:7293:ex:points:0":"❗起こる (おこる): to happen (intransitive verb); vs 起こす (transitive verb: to cause / to wake someone up); 〜かもしれない = might …","grammar:7293:ex:points:1":"事が起こる: an incident happens.","grammar:7293:ex2:trans":"A major accident happened.","grammar:7293:ex2:structure":"〜が起こりました","grammar:7293:ex2:words:0:zh":"big","grammar:7293:ex2:words:0:note":"おおきな","grammar:7293:ex2:words:0:pos":"pre-noun adjectival","grammar:7293:ex2:words:1:zh":"accident","grammar:7293:ex2:words:1:note":"じこ","grammar:7293:ex2:words:1:pos":"noun","grammar:7293:ex2:words:2:zh":"(nominative)","grammar:7293:ex2:words:2:pos":"particle","grammar:7293:ex2:words:3:zh":"occurred","grammar:7293:ex2:words:3:note":"おこりました","grammar:7293:ex2:words:3:pos":"verb","grammar:7293:ex2:points:0":"❗事故が起こる: an accident happens (intransitive verb).","grammar:7293:ex2:points:1":"事故が起こる: an accident occurs.","grammar:7293:ex3:trans":"There's no telling when an earthquake will happen.","grammar:7293:ex3:structure":"noun ＋ は ＋ いつ ＋ 起こるか ＋ わかりません","grammar:7293:ex3:words:0:zh":"earthquake","grammar:7293:ex3:words:0:note":"じしん: earthquake","grammar:7293:ex3:words:0:pos":"noun","grammar:7293:ex3:words:1:zh":"marks the topic","grammar:7293:ex3:words:1:pos":"particle","grammar:7293:ex3:words:2:zh":"when","grammar:7293:ex3:words:2:pos":"question word","grammar:7293:ex3:words:3:zh":"happened","grammar:7293:ex3:words:3:note":"おこる: dictionary form","grammar:7293:ex3:words:3:pos":"verb","grammar:7293:ex3:words:4:zh":"question","grammar:7293:ex3:words:4:pos":"particle","grammar:7293:ex3:words:5:zh":"know","grammar:7293:ex3:words:5:note":"わかり: masu-form stem","grammar:7293:ex3:words:5:pos":"verb","grammar:7293:ex3:words:6:zh":"polite","grammar:7293:ex3:words:6:pos":"auxiliary verb","grammar:7293:ex3:words:7:zh":"denial","grammar:7293:ex3:words:7:pos":"auxiliary verb","grammar:7293:ex3:points:0":"「地震が起こる」 means that a natural disaster, an accident, or the like happens; 「起こる」 is an intransitive verb.","grammar:7293:ex3:points:1":"「いつ起こるか」 = question word + verb + か, which embeds a question inside a sentence as its content.","grammar:7293:ex3:points:2":"「わかりません」 expresses that you don't know.","grammar:7293:ex4:trans":"Something strange happened.","grammar:7293:ex4:structure":"〜が起こった","grammar:7293:ex4:words:0:zh":"strange","grammar:7293:ex4:words:0:note":"ふしぎ","grammar:7293:ex4:words:0:pos":"na-adjective","grammar:7293:ex4:words:1:zh":"(attributive form)","grammar:7293:ex4:words:1:pos":"auxiliary verb","grammar:7293:ex4:words:2:zh":"thing / matter","grammar:7293:ex4:words:2:pos":"noun","grammar:7293:ex4:words:3:zh":"(nominative)","grammar:7293:ex4:words:3:pos":"particle","grammar:7293:ex4:words:4:zh":"occurred","grammar:7293:ex4:words:4:note":"おこった","grammar:7293:ex4:words:4:pos":"verb","grammar:7293:ex4:points:0":"❗不思議なことが起こる: a strange thing happens.","grammar:7293:ex4:points:1":"不思議なことが起こる: something mysterious happens.","grammar:7293:ex5:trans":"I hope something fun happens.","grammar:7293:ex5:structure":"〜が起こるといいな","grammar:7293:ex5:words:0:zh":"fun","grammar:7293:ex5:words:0:note":"たのしい","grammar:7293:ex5:words:0:pos":"adjective","grammar:7293:ex5:words:1:zh":"thing / matter","grammar:7293:ex5:words:1:pos":"noun","grammar:7293:ex5:words:2:zh":"(nominative)","grammar:7293:ex5:words:2:pos":"particle","grammar:7293:ex5:words:3:zh":"happened","grammar:7293:ex5:words:3:note":"おこる","grammar:7293:ex5:words:3:pos":"verb","grammar:7293:ex5:words:4:zh":"(condition)","grammar:7293:ex5:words:4:pos":"particle","grammar:7293:ex5:words:5:zh":"good","grammar:7293:ex5:words:5:pos":"adjective","grammar:7293:ex5:words:6:zh":"(exclamation)","grammar:7293:ex5:words:6:pos":"particle","grammar:7293:ex5:points:0":"❗〜といいな: I hope … / it would be nice if …; 楽しいことが起こる = something fun happens.","grammar:7293:ex5:points:1":"起こるといいな: I hope it happens."},"7294":{"example:7294:exzh":"He often comes over to hang out.","example:7294:exzh2":"I'm often late.","example:7294:exzh3":"There are often meetings.","example:7294:exzh4":"She often reads books.","example:7294:exzh5":"I often go to the same places."},"7295":{"example:7295:exzh":"The sky at dusk is beautiful.","example:7295:exzh2":"I take a walk at dusk.","example:7295:exzh3":"The light at dusk is wonderful.","example:7295:exzh4":"I felt the wind at dusk.","example:7295:exzh5":"The sea at dusk is quiet."},"7296":{"example:7296:exzh":"He is known as a cardinal.","example:7296:exzh2":"The cardinal's decision is important.","example:7296:exzh3":"This cardinal will solve the problem.","example:7296:exzh4":"The cardinal's role is significant.","example:7296:exzh5":"He is one of the key cardinals."},"7297":{"example:7297:exzh":"He works as a board member.","example:7297:exzh2":"The board meets every month.","example:7297:exzh3":"A board member's role is important.","example:7297:exzh4":"A new board member has been chosen.","example:7297:exzh5":"She is a member of the board."},"7298":{"example:7298:exzh":"I feel gloomy today.","example:7298:exzh2":"She always has a gloomy look on her face.","example:7298:exzh3":"I'm listening to gloomy music.","example:7298:exzh4":"He tends to get depressed.","example:7298:exzh5":"When you feel gloomy, it helps to take a walk."},"7299":{"example:7299:exzh":"Ninja can move quickly.","example:7299:exzh2":"The ninja in movies are really cool.","example:7299:exzh3":"When he was a child, he wanted to be a ninja.","example:7299:exzh4":"Ninja are known as stealthy ones.","example:7299:exzh5":"Many ninja appear in Japanese legends."}};